 for p in [root/'frozen-isolated'/n for n in ['status.tsv','target-isolation.json','library.log','submitted-tests.log','doctests.log','public-api.log','fmt.log','clippy.log']]:
  print('\nFILE',p)
  print(p.read_text())
PY

